func jetStreamObserverSubjects(bucket string) (leader, direct []string) {
	for _, prefix := range []string{"$JS.API", "$JS.gru.API"} {
		leader = append(leader, prefix+".STREAM.MSG.GET.KV_"+bucket)
		direct = append(direct, prefix+".DIRECT.GET.KV_"+bucket, prefix+".DIRECT.GET.KV_"+bucket+".>")
	}
	return leader, direct
}

func testRolloutJetStreamWithObserver(t *testing.T, bucket string) (jetstream.JetStream, *nats.Conn) {
	t.Helper()
	auth := newAuthenticatedNATS(t, "gru")
	runtime, err := auth.start(t, t.Context(), natscell.Config{Cell: "gru", Embedded: &natscell.Embedded{}})
	if err != nil {
		t.Fatal(err)
	}
	user, err := nkeys.CreateUser()
	if err != nil {
		t.Fatal(err)
	}
	defer user.Wipe()
	public, err := user.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	leader, direct := jetStreamObserverSubjects(bucket)
	claim := jwt.NewUserClaims(public)
	claim.IssuerAccount = auth.cellID
	claim.Expires = time.Now().Add(5 * time.Minute).Unix()
	claim.Pub.Deny = jwt.StringList{">"}
	claim.Sub.Allow = append(jwt.StringList(leader), direct...)
	credentials := testBrokerJWTUserWithKey(t, auth.root, "jetstream-observer.creds", auth.account, user, claim)
	dialer := &jetStreamObserverDialer{Dialer: &tls.Dialer{NetDialer: &net.Dialer{Timeout: 5 * time.Second}, Config: runtime.BrokerTLS().PeerConfig()}}
	observer, err := nats.Connect(runtime.URL(), nats.UserCredentials(credentials), nats.SetCustomDialer(dialer), nats.NoReconnect(), nats.Timeout(5*time.Second))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(observer.Close)
	return runtime.JetStream(), observer
}

func watchJetStreamLeaderReads(t *testing.T, observer *nats.Conn, bucket string) func() int {
	t.Helper()
	leader, direct := jetStreamObserverSubjects(bucket)
	subscribe := func(subjects []string) []*nats.Subscription {
		var subscriptions []*nats.Subscription
		for _, subject := range subjects {
			subscription, err := observer.SubscribeSync(subject)
			if err != nil {
				t.Fatal(err)
			}
			subscriptions = append(subscriptions, subscription)
		}
		return subscriptions
	}
	leaderSubscriptions, directSubscriptions := subscribe(leader), subscribe(direct)
	if err := observer.Flush(); err != nil {
		t.Fatal(err)
	}
	return func() int {
		t.Helper()
		if err := observer.Flush(); err != nil {
			t.Fatal(err)
		}
		if err := observer.LastError(); err != nil {
			t.Fatalf("JetStream observer authorization failed: %v", err)
		}
		reads := 0
		for _, subscription := range leaderSubscriptions {
			count, _, err := subscription.Pending()
			_ = subscription.Unsubscribe()
			if err != nil {
				t.Fatal(err)
			}
			reads += count
		}
		for _, subscription := range directSubscriptions {
			count, _, err := subscription.Pending()
			_ = subscription.Unsubscribe()
			if err != nil || count != 0 {
				t.Fatalf("authorization used follower reads=%d: %v", count, err)
			}
		}
		return reads
	}
}

type fakeRolloutSession struct {
	mu        sync.Mutex
	step      []byte
	release   []byte
	exchanges []host.RolloutExchange
}

func (s *fakeRolloutSession) RolloutExchange(_ context.Context, exchange host.RolloutExchange) (host.RolloutStep, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.exchanges = append(s.exchanges, exchange)
	return host.RolloutStep{Step: s.step}, nil
}

func (s *fakeRolloutSession) FetchRelease(_ context.Context, _ string, dst io.Writer) error {
	_, err := dst.Write(s.release)
	return err
}

func (*fakeRolloutSession) SessionLost() bool { return false }

func (s *fakeRolloutSession) last() (host.RolloutExchange, int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if len(s.exchanges) == 0 {
		return host.RolloutExchange{}, 0
	}
	return s.exchanges[len(s.exchanges)-1], len(s.exchanges)
}

func followHostRollouts(h hostRollout) func(context.Context, host.RolloutSession) {
	return func(ctx context.Context, session host.RolloutSession) {
		identity, err := rolloutexec.ProcessIdentity(h.cell, h.node, "")
		if err != nil {
			slog.WarnContext(ctx, "host rollouts disabled", "error", err)
			return
		}
		leaders, err := trust.ParseKeyring(h.controller)
		if err != nil {
			slog.WarnContext(ctx, "host rollouts disabled", "error", err)
			return
		}
		if err := os.MkdirAll(h.spool, 0o700); err != nil {
			slog.WarnContext(ctx, "host rollouts disabled", "error", err)
			return
		}
		relay := &rolloutexec.Relay{Cell: h.cell, Unit: h.node, SystemdUnit: selfupdate.HostUnit, Leaders: leaders,
			Dir: h.spool, Layout: h.layout, Sources: []rolloutexec.BinarySource{session.FetchRelease}}
		refused := false
		for {
			select {
			case <-ctx.Done():
				return
			case <-time.After(cmp.Or(h.interval, rolloutexec.DefaultProofInterval)):
			}
			if session.SessionLost() {
				return
			}
			now := time.Now().UTC()
			proof := identity
			proof.ObservedAt = now
			wire, err := rolloutexec.SignHealthProof(proof, h.identity, now)
			if err != nil {
				slog.WarnContext(ctx, "host rollouts stopped", "error", err)
				return
			}
			reply, err := relay.Reply()
			if err != nil {
				slog.WarnContext(ctx, "host rollout reply is unreadable", "error", err)
			}
			// An operator holding a restart here (TS-578) holds the host's
			// step too: the leader sends none, and none is spooled.
			holds, _ := filepath.Glob(filepath.Join(h.stateRoot, "*"+host.RestartHoldSuffix))
			held := h.stateRoot != "" && len(holds) > 0
			step, err := session.RolloutExchange(ctx, host.RolloutExchange{Proof: wire, Reply: reply, Held: held})
			if err != nil {
				// A controller without rollouts answers every exchange the
				// same way; say so once.
				if !refused && ctx.Err() == nil {
					slog.InfoContext(ctx, "host rollout exchange not accepted", "error", err)
				}
				refused = true
				continue
			}
			refused = false
			if len(step.Step) == 0 || held {
				continue
			}
			if err := relay.Spool(ctx, step.Step); err != nil && ctx.Err() == nil {
				slog.WarnContext(ctx, "host rollout step not spooled", "error", err)
			}
		}
	}
}

func (r *Relay) Spool(ctx context.Context, wire []byte) error {
	command, _, err := VerifyStepCommand(wire, r.Cell, r.Unit, r.Leaders, r.now())
	if err != nil {
		// Expired, or not this unit's: the leader posts a fresh one.
		return nil
	}
	path := filepath.Join(r.Dir, spoolStep)
	if current, err := os.ReadFile(path); err == nil && bytes.Equal(current, wire) {
		return nil
	}
	fetchErr := r.fetch(ctx, command.Digest)
	return errors.Join(fetchErr, writeFileAtomic(path, wire, 0o600))
}

// fetch spools the binary of digest unless the node already staged it, and
// removes every other spooled binary.
func (r *Relay) fetch(ctx context.Context, digest string) error {
	entries, err := os.ReadDir(r.Dir)
	if err != nil {
		return err
	}
	name := spoolReleasePrefix + digest
	for _, entry := range entries {
		if entry.Name() != name && (strings.HasPrefix(entry.Name(), spoolReleasePrefix) || strings.HasPrefix(entry.Name(), ".")) {
			_ = os.Remove(filepath.Join(r.Dir, entry.Name()))
		}
	}
	if _, err := os.Stat(r.Layout.BinaryPath(digest)); err == nil {
		return nil
	}
	if _, err := os.Stat(filepath.Join(r.Dir, name)); err == nil || len(r.Sources) == 0 {
		return nil
	}
	var failures []error
	for _, source := range r.Sources {
		err := writeVerified(ctx, filepath.Join(r.Dir, name), digest, source)
		if err == nil {
			return nil
		}
		failures = append(failures, err)
	}
	return fmt.Errorf("fetch release %s: %w", short(digest), errors.Join(failures...))
}

// Reply returns the agent's newest reply for the unit, nil when it has
// none.
func (r *Relay) Reply() ([]byte, error) {
	data, err := os.ReadFile(filepath.Join(r.Layout.Root, ReplyFile(r.SystemdUnit)))
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var reply StepReply
	if len(data) > maxReplyBytes || json.Unmarshal(data, &reply) != nil || reply.Unit != r.Unit {
		return nil, fmt.Errorf("%w: rollout step reply", ErrInvalid)
	}
	return data, nil

func writeVerified(ctx context.Context, path, digest string, source BinarySource) error {
	file, err := os.CreateTemp(filepath.Dir(path), ".download-")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	defer file.Close()
	hash := sha256.New()
	if err := source(ctx, digest, &limitWriter{w: io.MultiWriter(file, hash), left: selfupdate.MaxBinaryBytes}); err != nil {
		return err
	}
	if hex.EncodeToString(hash.Sum(nil)) != digest {
		return fmt.Errorf("%w: fetched bytes differ from release %s", ErrInvalid, short(digest))
	}
	if err := file.Close(); err != nil {
		return err
	}
	return os.Rename(file.Name(), path)
}

func VerifyHealthProof(wire []byte, cell, unit string, keys trust.Keyring, now time.Time) (HealthProof, error) {
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return HealthProof{}, err
	}
	payload, err := trust.VerifyCurrent(envelope, healthScope(cell, unit), keys, now,
		trust.Policy{MaxLifetime: HealthLifetime, ClockSkew: healthClockSkew})
	if err != nil {
		return HealthProof{}, err
	}
	var proof HealthProof
	if err := protocol.DecodeStrict(payload, &proof, trust.MaxPayloadBytes); err != nil {
		return HealthProof{}, err
	}
	if err := proof.validate(); err != nil {
		return HealthProof{}, err
	}
	if proof.Cell != cell || proof.Unit != unit || proof.ObservedAt.After(now.Add(healthClockSkew)) ||
		proof.ObservedAt.Before(envelope.IssuedAt.Add(-healthClockSkew)) {
		return HealthProof{}, fmt.Errorf("%w: health proof binding", ErrInvalid)
	}
	return proof, nil
}

func ProcessIdentity(cell, unit, executable string) (HealthProof, error) {
	if executable == "" {
		executable = "/proc/self/exe"
	}
	digest, err := hashExecutable(executable)
	if err != nil {
		return HealthProof{}, fmt.Errorf("hash running executable: %w", err)
	}
	var nonce [16]byte
	if _, err := rand.Read(nonce[:]); err != nil {
		return HealthProof{}, err
	}
	return HealthProof{Schema: HealthSchema, Cell: cell, Unit: unit, BinarySHA256: digest,
		ProcessID: int64(os.Getpid()), StartNonce: hex.EncodeToString(nonce[:])}, nil
}

func hashExecutable(path string) (string, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer file.Close()
	hash := sha256.New()
	if _, err := io.Copy(hash, file); err != nil {
		return "", err
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

