func (c *rolloutControl) Exchange(ctx context.Context, registration host.Registration, exchange host.RolloutExchange,
) (host.RolloutStep, error) {
	hosts := c.hosts.Load()
	if hosts == nil {
		return host.RolloutStep{}, errors.New("the rollout executor is not running")
	}
	node := registration.Node
	if hosts.colocated(node) {
		return host.RolloutStep{}, errors.New("a host on a controller's VM moves with its controller")
	}
	if len(exchange.Reply) > maxHostReply {
		return host.RolloutStep{}, errors.New("host rollout reply is too large")
	}
	now := time.Now()
	hosts.mu.Lock()
	if last, seen := hosts.last[node]; seen && now.Sub(last) < rolloutexec.DefaultProofInterval/2 {
		hosts.mu.Unlock()
		return host.RolloutStep{}, errors.New("host rollout exchange is too frequent")
	}
	hosts.last[node] = now
	hosts.mu.Unlock()
	public, err := decodePublicKey(registration.PublicKey)
	if err != nil {
		return host.RolloutStep{}, err
	}
	keys, err := trust.ParseKeyring(public)
	if err != nil {
		return host.RolloutStep{}, err
	}
	if err := hosts.collector.ObserveFrom(node, exchange.Proof, keys); err != nil {
		return host.RolloutStep{}, fmt.Errorf("host health proof: %w", err)
	}
	hosts.mu.Lock()
	if exchange.Held {
		hosts.held[node] = now
	} else {
		delete(hosts.held, node)
	}
	hosts.mu.Unlock()
	membership, err := protocol.EncodeJSON(rollout.HostMembership{Node: node, PublicKey: registration.PublicKey})
	if err != nil {
		return host.RolloutStep{}, err
	}
	if err := putChanged(ctx, hosts.board, rollout.HostMembershipKey(node), membership); err != nil {
		return host.RolloutStep{}, err
	}
	// Root independently verifies the original signature and current membership.
	if c.conn != nil {
		if err := c.conn.Publish(protocol.RolloutProofSubject(c.cell, node), exchange.Proof); err != nil {
			return host.RolloutStep{}, err
		}
	}
	if len(exchange.Reply) > 0 {
		var reply rolloutexec.StepReply
		if err := json.Unmarshal(exchange.Reply, &reply); err != nil || reply.Unit != node {
			return host.RolloutStep{}, errors.New("host rollout reply is invalid")
		}
		if err := putChanged(ctx, hosts.board, rolloutexec.ReplyKey(node), exchange.Reply); err != nil {
			return host.RolloutStep{}, err
		}
	}
	entry, err := hosts.board.Get(ctx, rolloutexec.StepKey(node))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return host.RolloutStep{}, nil
	}
	if err != nil {
		return host.RolloutStep{}, err
	}
	return host.RolloutStep{Step: entry.Value()}, nil
}

func (s *Store) PublishRelease(ctx context.Context, epoch uint64, release Release) (Release, error) {
	if release.ReleaseSequence > 0 || len(release.SequenceMigration) > 0 || release.SequenceMigrationSHA256 != "" || release.RollbackOf != 0 {
		return Release{}, fmt.Errorf("%w: sequenced releases require signature admission; rollbacks require retained generation", ErrInvalid)
	}
	if err := rejectSequencedReceipt(release.Receipt); err != nil {
		return Release{}, err
	}
	return s.publishRelease(ctx, epoch, release, false)
}

func (s *Store) publishRelease(ctx context.Context, epoch uint64, release Release, rollback bool) (Release, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if bad, err := s.IsKnownBad(ctx, release.Digest); err != nil {
		return Release{}, err
	} else if bad {
		return Release{}, ErrKnownBad
	}
	for range cellCASAttempts {
		desired, revision, err := s.Desired(ctx)
		if err != nil {
			return Release{}, err
		}
		seeded, err := s.seedReleaseOrdering(ctx, desired)
		if err != nil {
			return Release{}, err
		}
		next := seeded
		normalized := release
		normalized.Generation = desired.Generation() + 1
		normalized.ID = generationKey(s.cell, normalized.Generation)
		normalized.CreatedAt = release.CreatedAt.UTC()
		if err := normalized.validate(); err != nil {
			return Release{}, err
		}
		if !rollback {
			if err := advanceReleaseOrdering(&next, normalized, s.cell); err != nil {
				return Release{}, err
			}
		}
		if desired.Generation() > 0 && desired.Release.Digest == release.Digest {
			retry, err := s.retryUntouchedRelease(ctx, desired.Release, release)
			if err != nil {
				return Release{}, err
			}
			if !retry {
				if desired.SchemaVersion != DesiredSchemaVersion || desired.OrderingFloor.ReleaseSequence != next.OrderingFloor.ReleaseSequence || desired.LegacyFloor.Generation != next.LegacyFloor.Generation || desired.LegacyIssuanceFloor.Generation != next.LegacyIssuanceFloor.Generation {
					if err := s.writeDesired(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
						continue
					} else if err != nil {
						return Release{}, err
					}
				}
				return desired.Release, ErrReleaseUnchanged
			}
		}
		next.Release = normalized
		next.SchemaVersion = DesiredSchemaVersion
		if err := next.validate(s.cell); err != nil {
			return Release{}, err
		}
		// The generation being replaced is retained before the record
		// moves; a copy lost to a crash is written again by the next
		// publish, since the record still holds it.
		if desired.Generation() > 0 {
			if err := s.retain(ctx, epoch, desired.Release); err != nil {
				return Release{}, err
			}
		}
		if err := s.writeDesired(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else if err != nil {
			return Release{}, err
		}
		if newest := next.Generation(); newest > ReleaseHistory {
			// Best effort: a missed purge only keeps one more old copy.
			oldest := newest - ReleaseHistory
			state, _, err := s.Cell(ctx)
			if err == nil && state.ActiveRolloutID != entityid.Derive(ControllerReleaseDomain, ReleaseRolloutID(oldest)) &&
				state.ActiveRolloutID != entityid.Derive(HostReleaseDomain, ReleaseRolloutID(oldest)) && s.fencer.Guard(ctx, epoch) == nil {
				_ = s.kv.Purge(ctx, generationKey(s.cell, oldest))
			}
		}

func (s *Store) ReleasePins(ctx context.Context) (rollback, knownBad []string, err error) {
	for range cellCASAttempts {
		desired, revision, err := s.Desired(ctx)
		if err != nil {
			return nil, nil, err
		}
		rollback, knownBad, err := s.collectReleasePins(ctx, desired)
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			// A purge can follow the desired write without changing its revision.
			continue
		}
		if err != nil {
			return nil, nil, err
		}
		_, observedRevision, err := s.Desired(ctx)
		if err != nil {
			return nil, nil, err
		}
		// Publication can retain and prune generations during the inventory.
		if observedRevision == revision {
			return rollback, knownBad, nil
		}
	}
	return nil, nil, ErrConflict
}

func (s *Store) collectReleasePins(ctx context.Context, desired Desired) (rollback, knownBad []string, err error) {
	releases, err := s.retainedReleases(ctx, desired)
	if err != nil {
		return nil, nil, err
	}
	for _, release := range releases {
		rollback = append(rollback, release.Digest)
	}
	state, _, err := s.Cell(ctx)
	if err != nil {
		return nil, nil, err
	}
	knownBad = slices.Clone(state.KnownBad)
	keys, err := releasechannel.PinKeys(ctx, s.kv, "knownbad.*")
	if err != nil {
		return nil, nil, err
	}
	for _, key := range keys {
		digest := strings.TrimPrefix(key, "knownbad.")
		if !digestRE.MatchString(digest) {
			return nil, nil, fmt.Errorf("%w: known-bad key %q", ErrInvalid, key)
		}
		knownBad = append(knownBad, digest)
	}
	// A rollout's predecessor may predate the retained generation window,
	// or be the image's baked binary, which has no generation of its own.
	if state.ActiveRolloutID != "" {
		record, _, active, err := s.Active(ctx)
		if err != nil {
			return nil, nil, err
		}
		if active {
			rollback = append(rollback, record.FromDigest)
			knownBad = append(knownBad, record.KnownBad...)
		}
	}
	slices.Sort(rollback)
	slices.Sort(knownBad)
	return slices.Compact(rollback), slices.Compact(knownBad), nil
}

func openChannelBucket(ctx context.Context, js jetstream.JetStream, replicas int) (jetstream.KeyValue, error) {
	for {
		ctx := observability.StartTrace(ctx)
		kv, err := js.KeyValue(ctx, releasechannel.Bucket)
		if errors.Is(err, jetstream.ErrBucketNotFound) {
			kv, err = js.CreateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: releasechannel.Bucket,
				Storage: jetstream.FileStorage, Replicas: replicas, History: 4, MaxValueSize: releasechannel.MaxValueBytes})
		}
		if err == nil {
			return kv, nil
		}
		slog.WarnContext(ctx, "open the release channel bucket", observability.ComponentKey, "rollout", "error", err)
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(5 * time.Second):
		}
	}
}

func (c *rolloutControl) consumeChannel(ctx context.Context, store *rollout.Store, kv jetstream.KeyValue, epoch uint64,
	wire []byte, now time.Time,
) error {
	architectures := slices.Clone(c.architectures)
	if c.managedArchitecture != nil {
		architecture, err := c.managedArchitecture(ctx)
		if err != nil {
			return fmt.Errorf("observe managed host architecture for release channel: %w", err)
		}
		if !slices.Contains(architectures, architecture) {
			architectures = append(architectures, architecture)
			slices.Sort(architectures)
		}
	}
	status := releasechannel.Status{Schema: releasechannel.StatusSchema, Cell: strings.ToUpper(c.cell), UpdatedAt: now,
		Environment: c.environment, Architectures: architectures}
	var channel releasechannel.Channel
	if len(wire) == 0 {
		status.State, status.Reason = releasechannel.StateRolling, "the cell has no release channel"
	} else if err := json.Unmarshal(wire, &channel); err != nil {
		status.State, status.Reason = releasechannel.StateFailed, "the channel does not decode: "+err.Error()
	} else {
		status.RunNumber, status.ReleaseSequence = channel.RunNumber, channel.ReleaseSequence
		if release.ValidSourceRevision(channel.SourceRevision) {
			status.SourceRevision = channel.SourceRevision
		}
		if status.State, status.Reason, err = c.channelState(ctx, store, epoch, channel, now); err != nil {
			return err
		}
	}
	rollback, knownBad, err := store.ReleasePins(ctx)
	if err != nil {
		return err
	}
	status.Pins = &releasechannel.ReleasePins{Rollback: rollback, KnownBad: knownBad}
	status.Reason = releasechannel.Clip(status.Reason)
	return c.report(ctx, kv, status)
}

// report stores the leader's report in the bucket and publishes it for
// fan-in when it differs from the stored one. The stored report, not this
// leader's memory, decides, so a report a deposed leader left is replaced.
func (c *rolloutControl) report(ctx context.Context, kv jetstream.KeyValue, status releasechannel.Status) error {
	key := releasechannel.StatusKey(status.Cell)
	entry, err := kv.Get(ctx, key)
	if err == nil {
		var stored releasechannel.Status
		if json.Unmarshal(entry.Value(), &stored) == nil && sameReport(stored, status) &&
			!releasechannel.PinRefreshDue(stored.UpdatedAt, status.UpdatedAt) {
			c.reported.Store(&stored)
			return nil
		}
	} else if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return err
	}
	wire, err := json.Marshal(status, json.Deterministic(true))
	if err != nil {
		return err
	}
	if _, err := kv.Put(ctx, key, wire); err != nil {
		return err
	}
	if c.conn != nil {
		if err := c.conn.Publish(protocol.ReleaseStatusSubject(c.cell), wire); err != nil {
			slog.WarnContext(ctx, "publish the release channel status", observability.ComponentKey, "rollout", "error", err)
		}
	}
	// A repeat of the logged run, state and reason is steady state: DEBUG.
	level := slog.LevelDebug
	if logged := c.logged; logged == nil || logged.RunNumber != status.RunNumber || logged.State != status.State ||
		logged.Reason != status.Reason {
		level = slog.LevelInfo
		c.logged = &status
	}
	slog.Log(ctx, level, "release channel status", observability.ComponentKey, "rollout", "run", status.RunNumber,
		"state", status.State, "reason", status.Reason)
	c.reported.Store(&status)
	return nil

func PinKeys(ctx context.Context, kv jetstream.KeyValue, filter string) ([]string, error) {
	watcher, err := kv.WatchFiltered(ctx, []string{filter}, jetstream.MetaOnly(), jetstream.IgnoreDeletes())
	if err != nil {
		return nil, err
	}
	defer watcher.Stop()
	var keys []string
	for {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case entry, open := <-watcher.Updates():
			if !open {
				return nil, errors.New("release pin watcher closed before inventory completed")
			}
			if entry == nil {
				if err := ctx.Err(); err != nil {
					return nil, err
				}
				return keys, nil
			}
			keys = append(keys, entry.Key())
		}
	}
}

func (g rolloutGate) Check(ctx context.Context, record rollout.Record, unit string) error {
	if err := g.cluster.Check(ctx, record, unit); err != nil {
		return err
	}
	if unit == "" {
		return nil
	}
	if record.Kind == rollout.KindHost {
		if err := g.hostRules(ctx, unit); err != nil {
			return err
		}
	}
	if g.fenced != nil {
		return g.fenced(ctx, unit)
	}
	return nil
}

func (g rolloutGate) hostRules(ctx context.Context, unit string) error {
	if g.held != nil && g.held(unit) {
		return fmt.Errorf("%w: an operator holds restarts on %s", rolloutexec.ErrGateHeld, unit)
	}
	if g.drainedSeats != nil {
		drained, err := g.drainedSeats(ctx)
		if err != nil {
			return fmt.Errorf("%w: read the TerraBase seats: %v", rolloutexec.ErrGateHeld, err)
		}
		if len(drained) > 0 {
			return fmt.Errorf("%w: TerraBase seats %s are out of rotation", rolloutexec.ErrGateHeld,
				strings.Join(slices.Sorted(maps.Keys(drained)), ", "))
		}
	}
	if g.serving != nil {
		return g.serving(ctx, unit)
	}
	return nil
}

// terraBaseMembers is a cell's TerraBase desired state and reports.
type terraBaseMembers struct {
	desired map[string]uint64
	reports []host.Report
}

func (m terraBaseMembers) ListDesired(context.Context, string) ([]host.Desired, error) {
	var out []host.Desired
	for node, generation := range m.desired {
		out = append(out, host.Desired{Node: node, Role: "terrabase", Generation: generation})
	}
	return out, nil
}

func (m terraBaseMembers) ListHosts(context.Context) ([]host.HostStatus, error) {
	return []host.HostStatus{{Reports: m.reports}}, nil
}

func terraBaseServing(hosts seatrollout.Hosts) func(context.Context, string) error {
	return func(ctx context.Context, unit string) error {
		desired, err := hosts.ListDesired(ctx, terrabase.Role)
		if err != nil {
			return fmt.Errorf("%w: read the TerraBase members: %v", rolloutexec.ErrGateHeld, err)
		}
		members := map[string]uint64{}
		for _, d := range desired {
			if !d.Withdrawn {
				members[d.Node] = d.Generation
			}
		}
		if _, member := members[unit]; !member {
			return nil
		}
		statuses, err := hosts.ListHosts(ctx)
		if err != nil {
			return fmt.Errorf("%w: read the TerraBase members: %v", rolloutexec.ErrGateHeld, err)
		}
		serving := map[string]bool{}
		for _, status := range statuses {
			for _, report := range status.Reports {
				generation, member := members[report.Node]
				serving[report.Node] = serving[report.Node] || member && report.Role == terrabase.Role &&
					report.State == "running" && report.Generation == generation && time.Since(report.ObservedAt) < host.ReportMaxAge
			}
		}
		for _, node := range slices.Sorted(maps.Keys(members)) {
			if !serving[node] {
				return fmt.Errorf("%w: TerraBase member %s does not serve its desired generation", rolloutexec.ErrGateHeld, node)
			}
		}
		return nil
	}
}

type readyRolloutWatch struct {
	jetstream.KeyValue
	ready chan struct{}
}

func (kv readyRolloutWatch) WatchAll(ctx context.Context, opts ...jetstream.WatchOpt) (jetstream.KeyWatcher, error) {
	w, err := kv.KeyValue.WatchAll(ctx, opts...)
	if err == nil {
		select {
		case kv.ready <- struct{}{}:
		default:
		}
	}
	return w, err
}

func wakeOnRolloutChanges(ctx context.Context, board jetstream.KeyValue, wake chan<- struct{}) {
	for ctx.Err() == nil {
		watcher, err := board.WatchAll(ctx, jetstream.UpdatesOnly())
		if err == nil {
			for entry := range watcher.Updates() {
				if entry == nil {
					continue
				}
				// Step addresses are opaque; identify the leader's posts by their signed scope.
				if envelope, err := trust.DecodeEnvelope(entry.Value()); err == nil &&
					envelope.Scope.Domain == rolloutexec.StepDomain && entry.Key() == rolloutexec.StepKey(envelope.Scope.Slot) {
					continue
				}
				select {
				case wake <- struct{}{}:
				default:
				}
			}
			_ = watcher.Stop()
		} else {
			slog.WarnContext(ctx, "watch the rollout bucket", observability.ComponentKey, "rollout", "error", err)
		}
		select {
		case <-ctx.Done():
		case <-time.After(5 * time.Second):
		}
	}
}

func newAcceptedSpecTrust(t *testing.T, cfg *Config) {
	t.Helper()
	accepted := bootstrapstart.AcceptedIdentity{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
		Cell: cfg.NATS.Cell, Environment: "test"}
	roots := testSpecRoots(t)
	if spec := cfg.Controller.SpecTrust; spec != nil {
		accepted.DeploymentID, accepted.Environment = spec.DeploymentID, spec.Environment
		wire, err := os.ReadFile(spec.RootPublicKeyFile)
		if err != nil {
			t.Fatal(err)
		}
		block, _ := pem.Decode(wire)
		if block == nil || block.Type != "PUBLIC KEY" {
			t.Fatal("spec trust root is not a PEM public key")
		}
		key, err := x509.ParsePKIXPublicKey(block.Bytes)
		if err != nil {
			t.Fatal(err)
		}
		public, ok := key.(ed25519.PublicKey)
		if !ok {
			t.Fatal("spec trust root is not Ed25519")
		}
		roots, err = trust.ParseKeyring(public)
		if err != nil {
			t.Fatal(err)
		}
	}
	cfg.Controller.SpecTrust = nil
	previous := specAcceptedInputs
	specAcceptedInputs = func() (bootstrapstart.AcceptedIdentity, bootstrapstart.TrustInputs, error) {
		chain := trust.RootChain{Version: 1}
		identity := trust.ChainIdentity{DeploymentID: accepted.DeploymentID, Cell: accepted.Cell, Environment: accepted.Environment}
		verified, err := trust.VerifyRootChain(roots, identity, chain)
		return accepted, bootstrapstart.TrustInputs{ChainIdentity: identity, Genesis: roots, Chain: chain, Roots: verified}, err
	}
	t.Cleanup(func() { specAcceptedInputs = previous })
}

func newSpecRegistry(cfg Config, memberRole string) (*specRegistry, error) {
	r := &specRegistry{cell: cfg.NATS.Cell, fixed: map[string]WorkloadProfile{},
		signers: slices.SortedFunc(slices.Values(cfg.Controller.TrustedSigners), func(a, b TrustedSignerConfig) int {
			return strings.Compare(a.Actor, b.Actor)
		}), terraBaseCA: cfg.Controller.TerraBaseCACertFile != "",
		signedArtifactStore: cmp.Or(cfg.Controller.ArtifactStoreMaxBytes, delivery.DefaultArtifactStoreMaxBytes)}
	if cfg.NATS.Embedded != nil {
		r.artifactStoreLimit = cfg.NATS.Embedded.StoreLimitBytes() - specStoreHeadroomBytes
	}
	if _, signed := cfg.Controller.Workloads[terrabase.Role]; signed {
		r.terraBaseCA = true
	}
	if reconcile := cfg.Controller.OciReconcile; reconcile != nil {
		r.signedDesired, r.publicLB = reconcile.Desired, reconcile.PublicLB
	}
	if memberRole != "" {
		r.reserved = append(r.reserved, memberRole)
	}
	autoscaleConfig := cfg.Controller.Autoscale
	if err := r.loadTrust(cfg); err != nil {
		return nil, err
	}
	// Generation 0 is the signed config's generic workloads.
	r.current = cellspec.Spec{Schema: cellspec.Schema, Identity: r.identity, RequiresBinary: 1}
	for _, role := range slices.Sorted(maps.Keys(cfg.Controller.Workloads)) {
		profile := cfg.Controller.Workloads[role]
		if slices.Contains(r.reserved, role) || role == terrabase.Role {
			r.fixed[role] = profile
			continue
		}
		service := cellspec.Service{Role: role, Profile: profile}
		// Generation 0 reconciles exactly what the signed config already
		// reconciled.
		if autoscaleConfig != nil {
			for _, spec := range autoscaleConfig.Services {
				if spec.Role == role {
					service.Spec = &spec
				}
			}
		}
		r.current.Services = append(r.current.Services, service)
	}
	r.current.RequiresBinary = r.current.Level()
	return r, nil

func (r *specRegistry) open(ctx context.Context, js jetstream.JetStream, replicas int) error {
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: cellSpecBucket, History: 4,
		MaxValueSize: cellspec.MaxSignedBytes, Storage: jetstream.FileStorage, Replicas: replicas})
	if err != nil {
		return fmt.Errorf("open cell spec: %w", err)
	}
	r.kv = kv
	entry, err := kv.Get(ctx, cellSpecKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("read cell spec: %w", err)
	}
	return r.load(entry)
}

func (r *specRegistry) load(entry jetstream.KeyValueEntry) error {
	if entry.Operation() != jetstream.KeyValuePut {
		slog.Error("cell spec record was removed; keeping the current spec", observability.ComponentKey, "cellspec")
		return errors.New("stored cell spec was removed")
	}
	verified, err := r.verify(entry.Value(), nil)
	if newer := (*cellspec.NewerBinaryError)(nil); errors.As(err, &newer) {
		slog.Warn("stored cell spec needs a newer binary; keeping the current spec", observability.ComponentKey, "cellspec",
			"revision", entry.Revision(), "generation", newer.Generation, "requires_binary", newer.RequiresBinary,
			"binary_level", cellspec.BinaryLevel)
		return err
	}
	if err != nil {
		slog.Error("stored cell spec rejected; keeping the current spec", observability.ComponentKey, "cellspec",
			"revision", entry.Revision(), "error", err)
		return fmt.Errorf("stored cell spec rejected: %w", err)
	}
	r.adopt(verified.Spec, entry.Revision())
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.revision < entry.Revision() {
		return errors.New("stored cell spec could not be adopted")
	}
	return nil

func (r *rootRegistry) open(ctx context.Context, js jetstream.JetStream, replicas int) error {
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: rootChainBucket, History: 4,
		MaxValueSize: trust.MaxRootChainBytes, Storage: jetstream.FileStorage, Replicas: replicas})
	if err != nil {
		return fmt.Errorf("open root chain: %w", err)
	}
	r.kv = kv
	entry, err := kv.Get(ctx, rootChainKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("read root chain: %w", err)
	}
	r.load(ctx, entry)
	return nil
}

func controllerHostSpecCurrent(ctx context.Context, js jetstream.JetStream, services *specRegistry, entry jetstream.KeyValueEntry, rootHead string) error {
	if js == nil || js.Conn() == nil {
		return errors.New("controller host profile requires its current broker leader")
	}
	options := js.Options()
	var opts []nats.JSOpt
	if options.Domain != "" {
		opts = append(opts, nats.Domain(options.Domain))
	} else if options.APIPrefix != "" {
		opts = append(opts, nats.APIPrefix(options.APIPrefix))
	}
	reader, err := js.Conn().JetStream(opts...)
	if err != nil {
		return err
	}
	subject := "$KV." + cellSpecBucket + "." + cellSpecKey
	latest, err := reader.GetLastMsg("KV_"+cellSpecBucket, subject, nats.Context(ctx))
	if err != nil {
		return err
	}
	services.mu.Lock()
	adopted := services.revision
	services.mu.Unlock()
	if latest == nil || latest.Subject != subject || latest.Sequence == 0 || latest.Header.Get("KV-Operation") != "" || latest.Header.Get(jetstream.MarkerReasonHeader) != "" ||
		len(latest.Data) == 0 || len(latest.Data) > cellspec.MaxSignedBytes || latest.Sequence != entry.Revision() || adopted != entry.Revision() ||
		!bytes.Equal(latest.Data, entry.Value()) || services.roots.reply("").Head != rootHead {
		return errors.New("controller host profile or roots changed during recipient verification")
	}
	return rootTrustHeadCurrent(ctx, js, services.roots, rootHead)
}

func rootTrustHeadCurrent(ctx context.Context, js jetstream.JetStream, roots *rootRegistry, head string) error {
	if ctx == nil || js == nil || js.Conn() == nil || roots == nil || head == "" {
		return errors.New("root authority requires its current broker leader")
	}
	options := js.Options()
	var opts []nats.JSOpt
	if options.Domain != "" {
		opts = append(opts, nats.Domain(options.Domain))
	} else if options.APIPrefix != "" {
		opts = append(opts, nats.APIPrefix(options.APIPrefix))
	}
	reader, err := js.Conn().JetStream(opts...)
	if err != nil {
		return err
	}
	subject := "$KV." + rootChainBucket + "." + rootChainKey
	latest, err := reader.GetLastMsg("KV_"+rootChainBucket, subject, nats.Context(ctx))
	if err != nil {
		return err
	}
	if latest == nil || latest.Subject != subject || latest.Sequence == 0 || latest.Header.Get("KV-Operation") != "" || latest.Header.Get(jetstream.MarkerReasonHeader) != "" ||
		len(latest.Data) == 0 || len(latest.Data) > trust.MaxRootChainBytes {
		return errors.New("root authority has no current leader record")
	}
	chain, err := trust.DecodeRootChain(latest.Data)
	if err != nil {
		return err
	}
	verified, err := trust.VerifyRootChain(roots.genesis, roots.identity, chain)
	if err != nil {
		return err
	}
	if verified.Head != head || roots.reply("").Head != head {
		return errors.New("root authority changed during recipient verification")
	}
	return ctx.Err()
}

func observeManagedServices(ctx context.Context, client api.ControlClient, region, environment string,
	readiness func(context.Context, *api.Task) (func(context.Context) error, time.Time, error),
) ([]swarmruntime.ServiceObservation, error) {
	if client == nil || region == "" || environment == "" {
		return nil, errors.New("regional runtime observation source is unavailable")
	}
	listed, err := client.ListServices(ctx, &api.ListServicesRequest{})
	if err != nil {
		return nil, err
	}
	if listed == nil {
		return nil, errors.New("manager service list is unavailable")
	}
	var deadlines []context.CancelFunc
	defer func() {
		for _, cancel := range deadlines {
			cancel()
		}
	}()
	var confirmations []func(context.Context) (bool, error)
	services := make([]swarmruntime.ServiceObservation, 0, len(listed.Services))
	for _, service := range listed.Services {
		if service == nil {
			return nil, errors.New("manager service entry is unavailable")
		}
		labels := service.Spec.Annotations.Labels
		if labels[swarmruntime.LabelRegion] != region || labels[swarmruntime.LabelEnvironment] != environment || !entityid.Valid(labels[swarmruntime.LabelIntentID]) {
			continue
		}
		var probe func(context.Context, *api.Task) error
		var checks []func(context.Context) error
		var tasks []*api.Task
		unavailable := false
		// Native/stateful and function readiness have separate authenticated sources.
		if generic := service.Spec.Task.GetGeneric(); readiness != nil && generic != nil && generic.Kind == swarmruntime.ContainerKind &&
			labels[swarmruntime.LabelRole] != "terrabase" && labels[swarmruntime.LabelRole] != swarmruntime.FunctionWorkerRole {
			probe = func(probeCtx context.Context, task *api.Task) error {
				if deadline, known := ctx.Deadline(); known {
					var cancel context.CancelFunc
					probeCtx, cancel = context.WithDeadline(probeCtx, deadline)
					defer cancel()
				}
				check, deadline, err := readiness(probeCtx, task)
				if !deadline.IsZero() {
					if current, known := ctx.Deadline(); !known || deadline.Before(current) {
						var cancel context.CancelFunc
						ctx, cancel = context.WithDeadline(ctx, deadline)
						deadlines = append(deadlines, cancel)
					}
				}
				if err != nil || check == nil || deadline.IsZero() {
					unavailable = true
					return errors.New("current application readiness is unavailable")
				}
				checks, tasks = append(checks, check), append(tasks, task.Copy())
				return nil
			}
		}
		observed, err := swarmruntime.ObserveService(ctx, client, service.ID, probe)
		if err != nil {
			return nil, err
		}
		if observed.Region != region || observed.Environment != environment || observed.IntentID != labels[swarmruntime.LabelIntentID] {
			return nil, errors.New("managed service scope changed during observation")
		}
		confirmations = append(confirmations, func(ctx context.Context) (bool, error) {
			for index, task := range tasks {
				current, err := client.GetTask(ctx, &api.GetTaskRequest{TaskID: task.ID})
				if err != nil || current == nil || !proto.Equal(task, current.Task) || checks[index](ctx) != nil {
					unavailable = true
				}
			}
			confirmed, err := client.GetService(ctx, &api.GetServiceRequest{ServiceID: service.ID})
			if err != nil || confirmed == nil || !proto.Equal(service, confirmed.Service) {
				return false, errors.New("managed service changed during task readiness observation")
			}
			for _, check := range checks {
				if check(ctx) != nil {
					unavailable = true
				}
			}
			return unavailable, ctx.Err()
		})
		services = append(services, observed)
	}
	// Later services cannot extend the first captured proof or bypass its final check.
	for index, confirm := range confirmations {
		unavailable, err := confirm(ctx)
		if err != nil {
			return nil, err
		}
		observed := &services[index]
		if unavailable {
			observed.Readiness, observed.ReadyReplicas = "unknown", 0
			for index := range observed.Tasks {
				observed.Tasks[index].Ready = false
			}
		}
		if observed.Readiness != "observed" {
			observed.ReadinessReason = "current authenticated task material and application readiness source is unavailable"
		}
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		observed.ObservedAt = time.Now().UTC()
	}
	slices.SortFunc(services, func(a, b swarmruntime.ServiceObservation) int { return strings.Compare(a.ServiceID, b.ServiceID) })
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	return services, nil
}

func ObserveService(ctx context.Context, client api.ControlClient, serviceID string, probe func(context.Context, *api.Task) error) (ServiceObservation, error) {
	response, err := client.GetService(ctx, &api.GetServiceRequest{ServiceID: serviceID})
	if err != nil {
		return ServiceObservation{}, err
	}
	s := response.Service
	if s.Spec.GetReplicated() == nil {
		return ServiceObservation{}, errors.New("unsupported service mode")
	}
	view := ServiceObservation{ServiceID: s.ID, IntentID: s.Spec.Annotations.Labels[LabelIntentID], Role: s.Spec.Annotations.Labels[LabelRole], Region: s.Spec.Annotations.Labels[LabelRegion], Environment: s.Spec.Annotations.Labels[LabelEnvironment], RequestedReplicas: s.Spec.GetReplicated().Replicas, RequestedDigest: runtimeDigest(s.Spec), Readiness: "unknown", Tasks: []TaskObservation{}}
	if probe != nil {
		view.Readiness = "observed"
	}
	if s.UpdateStatus != nil {
		view.UpdateState = s.UpdateStatus.State.String()
	}
	listed, err := client.ListTasks(ctx, &api.ListTasksRequest{Filters: &api.ListTasksRequest_Filters{ServiceIDs: []string{s.ID}}})
	if err != nil {
		return ServiceObservation{}, err
	}
	for _, task := range listed.Tasks {
		observation := TaskObservation{TaskID: task.ID, NodeID: task.NodeID, Digest: runtimeDigest(api.ServiceSpec{Task: task.Spec}), State: task.Status.State.String()}
		if timestamp, err := types.TimestampFromProto(task.Status.Timestamp); err == nil {
			observation.UpdatedAt = timestamp
		}
		if task.Status.Err != "" {
			observation.Error = "task lifecycle failed"
		}
		if task.DesiredState == api.TaskStateRunning && task.Status.State == api.TaskStateRunning {
			view.RunningReplicas++
			if probe != nil {
				probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
				err := probe(probeCtx, task)
				cancel()
				if err == nil {
					observation.Ready = true
					view.ReadyReplicas++
				} else {
					observation.Error = "application readiness probe failed"
				}
			}
		}
		view.Tasks = append(view.Tasks, observation)
	}
	slices.SortFunc(view.Tasks, func(a, b TaskObservation) int { return strings.Compare(a.TaskID, b.TaskID) })
	view.ObservedAt = time.Now().UTC()
	return view, nil
}

func runtimeDigest(spec api.ServiceSpec) string {
	g := spec.Task.GetGeneric()
	if g == nil || g.Kind != ContainerKind || g.Payload == nil {
		return ""
	}
	c := new(api.ContainerSpec)
	if c.Unmarshal(g.Payload.Value) != nil {
		return ""
	}
	_, digest, _ := strings.Cut(c.Image, "@")
	return digest
}

func readBakedRuntimePriorityProfileAt(path string, ownerUID, ownerGID uint32) (uint64, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return 0, errors.New("runtime priority profile path is invalid")
	}
	parent := filepath.Dir(path)
	parentInfo, err := os.Lstat(parent)
	if err != nil {
		return 0, err
	}
	if !ownedRuntimePriorityPath(parentInfo, ownerUID, ownerGID, 0755, true) {
		return 0, errors.New("runtime priority profile directory is unsafe")
	}
	dirFD, err := unix.Open(parent, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return 0, err
	}
	defer unix.Close(dirFD)
	fileInfo, err := os.Lstat(path)
	if err != nil {
		return 0, err
	}
	if !ownedRuntimePriorityPath(fileInfo, ownerUID, ownerGID, 0644, false) || fileInfo.Size() < 1 || fileInfo.Size() > 1024 {
		return 0, errors.New("runtime priority profile file is unsafe")
	}
	fd, err := unix.Openat(dirFD, filepath.Base(path), unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return 0, err
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	openedInfo, err := file.Stat()
	if err != nil || !os.SameFile(fileInfo, openedInfo) ||
		!ownedRuntimePriorityPath(openedInfo, ownerUID, ownerGID, 0644, false) {
		return 0, errors.New("runtime priority profile changed while opening")
	}
	data, err := io.ReadAll(io.LimitReader(file, 1025))
	if err != nil {
		return 0, err
	}
	finalInfo, err := file.Stat()
	if err != nil || !os.SameFile(openedInfo, finalInfo) || finalInfo.Size() != int64(len(data)) ||
		finalInfo.ModTime() != openedInfo.ModTime() {
		return 0, errors.New("runtime priority profile changed while reading")
	}
	var profile bakedRuntimePriorityProfile
	if err := json.Unmarshal(data, &profile, json.RejectUnknownMembers(true)); err != nil {
		return 0, errors.New("runtime priority profile JSON is invalid")
	}
	if profile.Version != 1 || !validRuntimePriorityProfileID(profile.ProfileID) ||
		profile.SystemReserveBytes == 0 || profile.SystemReserveBytes > math.MaxInt64 ||
		profile.SystemReserveBytes%uint64(os.Getpagesize()) != 0 {
		return 0, errors.New("runtime priority profile values are invalid")
	}
	return profile.SystemReserveBytes, nil
}

func ownedRuntimePriorityPath(info os.FileInfo, uid, gid uint32, mode os.FileMode, directory bool) bool {
	if info == nil || info.IsDir() != directory || info.Mode()&os.ModeSymlink != 0 ||
		info.Mode()&os.ModeType != 0 && !directory || info.Mode().Perm() != mode {
		return false
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	return ok && stat.Uid == uid && stat.Gid == gid && stat.Mode&07777 == uint32(mode)
}

func validRuntimePriorityProfileID(value string) bool {
	if len(value) < 1 || len(value) > 128 {
		return false
	}
	for _, character := range value {
		if character >= 'a' && character <= 'z' || character >= 'A' && character <= 'Z' ||
			character >= '0' && character <= '9' || character == '.' || character == '_' ||
			character == ':' || character == '-' {
			continue
		}
		return false
	}
	return true
}

func NewController(ctx context.Context, cfg ControllerConfig) (*Controller, error) {
	if err := validateToken(cfg.Cell, "cell"); err != nil {
		return nil, err
	}
	if cfg.Conn == nil || cfg.JS == nil || cfg.Artifacts == nil || cfg.HostMutations == nil || len(cfg.ResponseKey) != ed25519.PrivateKeySize {
		return nil, errors.New("controller requires NATS, JetStream, ordered host mutations, artifact store and Ed25519 response key")
	}
	if cfg.AuthorityEpoch == nil || cfg.AuthorityGuard == nil {
		return nil, errors.New("controller requires authority epoch and guard")
	}
	managedEffectGate := cfg.ManagedEffectGate
	if managedEffectGate == nil {
		if gate, ok := cfg.HostMutations.(interface {
			BeginActiveWorkloadEffect(context.Context, uint64, authority.WorkloadScope) (func(), error)
		}); ok {
			managedEffectGate = gate.BeginActiveWorkloadEffect
		}
	}
	if cfg.ManagedRegistrationVerifier != nil && managedEffectGate == nil {
		return nil, errors.New("managed host registration requires a terminal effect gate")
	}
	replicas := cfg.StateReplicas
	if replicas == 0 {
		replicas = 3
	}
	if replicas < 1 || replicas > 5 {
		return nil, errors.New("invalid host state replica count")
	}
	state := cfg.State
	if state == nil {
		var err error
		state, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: stateBucket, History: 2, MaxValueSize: 64 << 10, MaxBytes: 256 << 20, Storage: jetstream.FileStorage, Replicas: replicas})
		if err != nil {
			return nil, fmt.Errorf("open host state: %w", err)
		}
	}
	status, err := state.Status(ctx)
	if err != nil {
		if cfg.State == nil && errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect host state: %w", ErrStateNotReady, err)
		}
		return nil, err
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("host state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	if err := rejectObsoleteRetirementState(ctx, state, cfg.Cell); err != nil {
		return nil, err
	}
	controlLog := cfg.ControlLog
	if controlLog == nil {
		controlLog, err = cfg.JS.Stream(ctx, "TS_CONTROL_LOG")
		if err != nil {
			return nil, fmt.Errorf("open ordered control log: %w", err)
		}
	}
	cacheCtx, cacheCancel := context.WithCancel(context.Background())
	return &Controller{cell: cfg.Cell, conn: cfg.Conn, state: state, controlLog: controlLog, mutations: cfg.HostMutations,
		managedVerifier: cfg.ManagedRegistrationVerifier, managedDesiredVerifier: cfg.ManagedDesiredVerifier,
		managedEffectGate: managedEffectGate, materialProvider: cfg.ManagedMaterialProvider,
		credentialFloor: cfg.ManagedCredentialFloor, volumeInspector: cfg.ManagedVolumeInspector, runtimeEffects: cfg.RuntimeEffects,

func (c *Controller) Register(ctx context.Context, r Registration) (Receipt, error) {
	id := entityid.Derive("host", r.Cell, r.Node)
	if r.ID != "" && r.ID != id {
		return Receipt{}, errors.New("host ID differs from its node identity")
	}
	r.ID = id
	if err := validateRegistration(r, c.cell); err != nil {
		return Receipt{}, err
	}
	if r.ManagedOCI != nil && r.ManagedPlacement == nil {
		return Receipt{}, errors.New("managed host registration requires current schema-3 placement pins")
	}
	authorityEpoch := c.authorityEpoch()
	if err := c.guard(ctx, authorityEpoch); err != nil {
		return Receipt{}, err
	}
	if r.ManagedMember != nil {
		if c.managedEffectGate == nil || r.ManagedPlacement == nil {
			return Receipt{}, errors.New("managed host registration requires a terminal effect gate and placement scope")
		}
		release, err := c.managedEffectGate(ctx, authorityEpoch, authority.WorkloadScope{
			DatabaseID: r.ManagedPlacement.DatabaseID, PartitionID: r.ManagedPlacement.PartitionID,
		})
		if err != nil {
			return Receipt{}, err
		}
		defer release()
	}
	c.registrationMu.Lock()
	defer c.registrationMu.Unlock()
	payload, operationID, err := mutationPayload(r)
	if err != nil {
		return Receipt{}, err
	}
	key := registrationSubjectKey(c.cell, r.Node)
	for range 8 {
		if r.ManagedMember != nil {
			if c.managedVerifier == nil {
				return Receipt{}, errors.New("managed host registration requires a current placement verifier")
			}
			if err := c.managedVerifier.VerifyManagedRegistration(ctx, r); err != nil {
				return Receipt{}, fmt.Errorf("verify managed host registration: %w", err)
			}
			if err := c.requireExclusiveManagedMember(ctx, r); err != nil {
				return Receipt{}, err
			}
		}
		current, revision, exists, err := c.readRegistration(ctx, r.Node)
		if err != nil {
			return Receipt{}, err
		}
		if exists {
			if (current.ManagedOCI == nil) != (r.ManagedOCI == nil) ||
				current.ManagedOCI != nil && (current.ManagedMember == nil || *current.ManagedOCI != *r.ManagedOCI ||
					*current.ManagedMember != *r.ManagedMember || current.FailureDomain != r.FailureDomain) {
				return Receipt{}, errors.New("host managed binding cannot be retargeted")
			}
			if r.Generation < current.Generation {
				return Receipt{}, errors.New("registration generation moved backward")
			}
			if r.Generation == current.Generation {
				if !sameJSON(r, current) {
					return Receipt{}, errors.New("registration changed without a generation increase")
				}
				return Receipt{r.Generation, revision}, nil
			}
		}
		if err := c.guard(ctx, authorityEpoch); err != nil {
			return Receipt{}, err
		}
		written, err := c.mutations.CommitHostMutation(ctx, authorityEpoch, authority.MutationRegistration, key, operationID, revision, payload)
		if err == nil {
			return Receipt{r.Generation, written}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return Receipt{}, err
		}
	}
	return Receipt{}, errors.New("registration contention")
}

func (c *Controller) markRetired(ctx context.Context, epoch uint64, node string, retired bool) error {
	if err := c.guard(ctx, epoch); err != nil {
		return err
	}
	data, operation, err := mutationPayload(retirement{Retired: retired})
	if err != nil {
		return err
	}
	for range 8 {
		mark, revision, err := c.readRetirement(ctx, node)
		if err != nil {
			return err
		}
		if mark.Retired == retired {
			return nil
		}
		_, err = c.mutations.CommitHostMutation(ctx, epoch, authority.MutationRetirement, registrationSubjectKey(c.cell, node), operation, revision, data)
		if err == nil {
			return nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return fmt.Errorf("mark %s retired=%t: %w", node, retired, err)
		}
	}
	return errors.New("host retirement contention")
}

// RetireIdle retires node if it holds no active allocation and reports
// whether it did. A retired node takes no new allocation until Unretire,
// also from a later leader: the mark is in the log and every desired
// commit reads it. Withdrawals still apply. The process lock excludes desired
// commits during the idle check; the captured epoch fences leadership changes.
func (c *Controller) RetireIdle(ctx context.Context, node string) (bool, error) {
	c.retireMu.Lock()
	defer c.retireMu.Unlock()
	epoch := c.authorityEpoch()
	if err := c.guard(ctx, epoch); err != nil {
		return false, err
	}
	desired, err := c.ListDesired(ctx, "")
	if err != nil {
		return false, err
	}
	for _, d := range desired {
		if d.Node == node && !d.Withdrawn {
			return false, nil
		}
	}
	if err := c.markRetired(ctx, epoch, node, true); err != nil {
		return false, err
	}
	return true, nil

func (c *Controller) ListHosts(ctx context.Context) ([]HostStatus, error) {
	if c.controlLog == nil {
		return nil, errors.New("ordered control log is required for host discovery")
	}
	prefix := protocol.Control(c.cell, "host", "registration", c.cell) + "."
	info, err := c.controlLogSubjects(ctx, prefix+"*")
	if err != nil {
		return nil, err
	}
	var hosts []HostStatus
	for subject := range info.State.Subjects {
		node, ok := strings.CutPrefix(subject, prefix)
		if !ok || validateToken(node, "node") != nil {
			return nil, errors.New("host registration subject is invalid")
		}
		r, registrationRevision, exists, err := c.readRegistration(ctx, node)
		if err != nil {
			return nil, err
		} else if !exists {
			continue
		}
		retirement, retirementRevision, err := c.readRetirement(ctx, node)
		if err != nil {
			return nil, err
		}
		status := HostStatus{Registration: r, Retired: retirement.Retired, Verified: !c.readOnly}
		s, _, exists, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
		if err != nil {
			return nil, err
		}
		if exists && s.RegistrationGeneration == r.Generation && time.Now().Before(s.ExpiresAt) {
			status.SessionExpiresAt = s.ExpiresAt
			for _, role := range r.Roles {
				report, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil {
					return nil, err
				}
				if !ok || report.Cell != c.cell || report.Node != r.Node || report.Environment != r.Environment || report.Role != role ||
					report.SessionID != s.SessionID || report.Epoch != s.Epoch || time.Since(report.ObservedAt) >= ReportMaxAge || report.ObservedAt.After(time.Now().Add(maxClockSkew)) {
					continue
				}
				desired, desiredRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil {
					return nil, err
				}
				if !ok || report.Generation != desired.Generation || report.Digest != desired.Digest || desired.Withdrawn && report.State == "running" ||
					validateManagedReportForDesired(report, desired) != nil {
					continue
				}
				confirmed, confirmedRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil || !ok || confirmedRevision != desiredRevision || !sameJSON(confirmed, desired) {
					return nil, errors.New("desired changed during host status read")
				}
				check, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil || !ok || check.ObservedAt.Before(report.ObservedAt) || !sameReportMeaning(check, report) ||
					check.SessionID != s.SessionID || check.Epoch != s.Epoch || check.Generation != desired.Generation || check.Digest != desired.Digest ||
					validateManagedReportForDesired(check, desired) != nil ||
					time.Since(check.ObservedAt) >= ReportMaxAge || check.ObservedAt.After(time.Now().Add(maxClockSkew)) || desired.Withdrawn && check.State == "running" {
					return nil, errors.New("report changed during host status read")
				}
				status.Reports = append(status.Reports, check)
			}
			check, _, ok, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
			if err != nil || !ok || check.RegistrationGeneration != r.Generation || check.SessionID != s.SessionID || check.Epoch != s.Epoch || !time.Now().Before(check.ExpiresAt) {
				return nil, errors.New("session changed during host status read")
			}
			status.SessionExpiresAt = check.ExpiresAt
		}
		confirmed, confirmedRevision, ok, err := c.readRegistration(ctx, node)
		if err != nil || !ok || confirmedRevision != registrationRevision || !sameJSON(confirmed, r) {
			return nil, errors.New("registration changed during host status read")
		}
		if _, revision, err := c.readRetirement(ctx, node); err != nil || revision != retirementRevision {
			return nil, errors.New("retirement changed during host status read")
		}
		hosts = append(hosts, status)
	}
	slices.SortFunc(hosts, func(a, b HostStatus) int { return strings.Compare(a.Registration.Node, b.Registration.Node) })
	return hosts, nil
}

func NewReader(ctx context.Context, cfg ReaderConfig) (*Reader, error) {
	if err := validateToken(cfg.Cell, "cell"); err != nil {
		return nil, err
	}
	if cfg.HostMutations == nil || cfg.Conn == nil {
		return nil, errors.New("reader requires NATS connection and ordered host mutation store")
	}
	state := cfg.State
	if state == nil {
		if cfg.JS == nil {
			return nil, errors.New("reader requires JetStream or host state")
		}
		var err error
		state, err = cfg.JS.KeyValue(ctx, stateBucket)
		if err != nil {
			return nil, err
		}
	}
	replicas := cfg.StateReplicas
	if replicas == 0 {
		replicas = 3
	}
	status, err := state.Status(ctx)
	if err != nil {
		return nil, err
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("host state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	controlLog := cfg.ControlLog
	if controlLog == nil {
		if cfg.JS == nil {
			return nil, errors.New("reader requires JetStream or control log")
		}
		controlLog, err = cfg.JS.Stream(ctx, "TS_CONTROL_LOG")
		if err != nil {
			return nil, err
		}
	}
	return &Reader{controller: &Controller{cell: cfg.Cell, conn: cfg.Conn, state: state, controlLog: controlLog, mutations: cfg.HostMutations, credentialFloor: cfg.ManagedCredentialFloor, readOnly: true}}, nil
}

func (r *Reader) ListHosts(ctx context.Context) ([]HostStatus, error) {
	return r.controller.ListHosts(ctx)
}

func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil
}

func (r *Reader) ReadHostMutation(ctx context.Context, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	if r == nil || r.stream == nil {
		return LogEntry{}, ErrNotFound
	}
	if err := validateMutationKey(kind, subjectKey); err != nil {
		return LogEntry{}, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	return readMutation(ctx, r.stream, r.scope, kind, subjectKey)
}

func NewWorkerMembershipSource(ctx context.Context, mutations *authority.Reader, hosts *host.Reader, grants *GrantStore,
	js jetstream.JetStream, cell string, public ed25519.PublicKey,
) (*WorkerMembershipSource, error) {
	if mutations == nil || hosts == nil || grants == nil || grants.kv == nil || js == nil || cell == "" || len(public) != ed25519.PublicKeySize {
		return nil, errors.New("worker membership requires concrete current readers and pinned response authority")
	}
	stream, err := grantLeaderReader(js)
	if err != nil {
		return nil, err
	}
	return &WorkerMembershipSource{mutations: mutations, hosts: hosts, grants: grants, stream: stream, cell: cell, public: bytes.Clone(public)}, nil
}

func (source *WorkerMembershipSource) Read(ctx context.Context, query WorkerMembershipQuery) (WorkerMembershipSnapshot, error) {
	fail := func(err error) (WorkerMembershipSnapshot, error) { return WorkerMembershipSnapshot{}, err }
	if source == nil || query.NodeID == "" || !entityid.Valid(query.RegistrationID) || query.InstanceID == "" {
		return fail(errors.New("worker membership locators are invalid"))
	}
	grant, revision, err := source.readGrant(ctx, query.InstanceID)
	if err != nil {
		return fail(err)
	}
	record := grant.SwarmMembership
	if query.Admission != nil {
		record = query.Admission
	}
	if record == nil {
		return fail(errors.New("worker membership has no retained dual-key admission"))
	}
	verified, err := VerifySwarmMembership(*record, source.public)
	if err != nil {
		return fail(err)
	}
	worker := verified.Worker()
	request, descriptor, err := ParseRetainedWorkerRequest(record.Transport.Request, record.Binding.IssuedAt)
	if err != nil || record.Binding.NodeID != query.NodeID || worker.RegistrationID != query.RegistrationID || worker.InstanceID != query.InstanceID ||
		worker.Cell != source.cell || descriptor.Cell != source.cell || entityid.Derive("host", descriptor.Cell, descriptor.Node) != query.RegistrationID {
		return fail(errors.New("worker membership locators differ from authenticated admission"))
	}
	snapshot, err := source.readSnapshot(ctx, descriptor.Node, grant, revision)
	if err != nil {
		return fail(err)
	}
	if query.Admission != nil {
		registration := snapshot.Registration
		role := "container"
		if slices.Contains(registration.Roles, "function-worker") {
			if len(registration.Roles) != 1 {
				return fail(errors.New("function worker registration must be dedicated"))
			}
			role = "wasm"
		}
		if snapshot.Retired || grant.Disabled || grant.TerminalOperationID != "" || grant.IdentityResetOperationID != "" ||
			!time.Now().Before(record.Binding.ExpiresAt) || registration.ID != worker.RegistrationID || registration.Generation != worker.Generation ||
			snapshot.Sequence != worker.Revision || registration.Environment != worker.Environment || registration.PublicKey != request.IdentityPublicKey ||
			registration.NATSUserPublicKey != request.NATSUserPublicKey || len(registration.Roles) == 0 || role != worker.Role {
			return fail(errors.New("worker admission differs from current registered recipient"))
		}
		if !grant.MatchesCompletedWorkerEnrollment(record.Transport) {
			return fail(errors.New("worker admission differs from the current completed enrollment"))
		}
		if !sameSwarmMembership(grant.SwarmMembership, record) {
			if _, err := source.grants.RecordSwarmMembership(ctx, grant, revision, *record); err != nil {
				return fail(err)
			}
		}
	}
	// Leader reads are required: two follower reads can both miss revocation.
	grant, revision, err = source.readGrant(ctx, query.InstanceID)
	if err != nil {
		return fail(err)
	}
	current, err := source.readSnapshot(ctx, descriptor.Node, grant, revision)
	if err != nil || !sameSwarmMembership(grant.SwarmMembership, record) || current.Sequence != snapshot.Sequence || !sameMembershipValue(current.Registration, snapshot.Registration) || current.Retired != snapshot.Retired {
		return fail(errors.New("worker membership changed during admission observation"))
	}
	confirmedGrant, confirmedRevision, err := source.readGrant(ctx, query.InstanceID)
	if err != nil || confirmedRevision != revision || !sameMembershipValue(confirmedGrant, grant) {
		return fail(errors.New("worker enrollment changed during ordered host reads"))
	}
	confirmed, err := source.readSnapshot(ctx, descriptor.Node, confirmedGrant, confirmedRevision)
	if err != nil || !sameMembershipValue(current, confirmed) {
		return fail(errors.New("worker registration or retirement changed during grant observation"))
	}
	return confirmed, nil
}

func (source *WorkerMembershipSource) readGrant(ctx context.Context, instanceID string) (Grant, uint64, error) {
	return readCurrentGrant(ctx, source.stream, instanceID)
}

// ReadCurrentGrant bypasses follower-local KV reads when revocation matters.
func ReadCurrentGrant(ctx context.Context, js jetstream.JetStream, instanceID string) (Grant, uint64, error) {
	if js == nil || instanceID == "" {
		return Grant{}, 0, errors.New("current enrollment grant reader is unavailable")
	}
	stream, err := grantLeaderReader(js)
	if err != nil {
		return Grant{}, 0, err
	}
	return readCurrentGrant(ctx, stream, instanceID)
}

func grantLeaderReader(js jetstream.JetStream) (nats.JetStreamContext, error) {
	if js == nil || js.Conn() == nil {
		return nil, errors.New("current enrollment grant requires a NATS connection")
	}
	options := js.Options()
	var opts []nats.JSOpt
	if options.Domain != "" {
		opts = append(opts, nats.Domain(options.Domain))
	} else if options.APIPrefix != "" {
		opts = append(opts, nats.APIPrefix(options.APIPrefix))
	}
	// The modern Stream API chooses follower DIRECT.GET for ordinary KV buckets.
	return js.Conn().JetStream(opts...)
}

func readCurrentGrant(ctx context.Context, stream nats.JetStreamContext, instanceID string) (Grant, uint64, error) {
	subject := "$KV." + GrantBucket + "." + grantKey(instanceID)
	entry, err := stream.GetLastMsg("KV_"+GrantBucket, subject, nats.Context(ctx))
	if err != nil {
		return Grant{}, 0, err
	}
	var grant Grant
	if entry == nil || entry.Subject != subject || entry.Sequence == 0 || entry.Header.Get("KV-Operation") != "" || entry.Header.Get(jetstream.MarkerReasonHeader) != "" ||
		protocol.DecodeStrict(entry.Data, &grant, MaxGrantBytes) != nil || grant.SchemaVersion != 1 || grant.InstanceID != instanceID {
		return Grant{}, 0, errors.New("worker enrollment grant is corrupt or deleted")
	}
	return grant, entry.Sequence, nil
}

func (source *WorkerMembershipSource) readSnapshot(ctx context.Context, node string, grant Grant, revision uint64) (WorkerMembershipSnapshot, error) {
	fail := func(err error) (WorkerMembershipSnapshot, error) { return WorkerMembershipSnapshot{}, err }
	subject := source.cell + "." + node
	entry, err := source.mutations.ReadHostMutation(ctx, authority.MutationRegistration, subject)
	if err != nil {
		return fail(err)
	}
	var registration host.Registration
	if protocol.DecodeStrict(entry.Payload, &registration, 64<<10) != nil || entry.Kind != authority.MutationRegistration || entry.SubjectKey != subject ||
		entry.Sequence == 0 || entry.Epoch == 0 || registration.ID != entityid.Derive("host", source.cell, node) || registration.Cell != source.cell || registration.Node != node {
		return fail(errors.New("worker registration log identity is invalid"))
	}
	statuses, err := source.hosts.ListHosts(ctx)
	if err != nil {
		return fail(err)
	}
	found, retired := false, true
	for _, status := range statuses {
		if status.Registration.ID != registration.ID {
			continue
		}
		if found || !sameMembershipValue(status.Registration, registration) {
			return fail(errors.New("worker registration changed during current host read"))
		}
		found, retired = true, status.Retired
	}
	if !found {
		return fail(errors.New("worker has no current registered host"))
	}
	confirmed, err := source.mutations.ReadHostMutation(ctx, authority.MutationRegistration, subject)
	if err != nil || confirmed.Sequence != entry.Sequence || !bytes.Equal(confirmed.Payload, entry.Payload) {
		return fail(errors.New("worker registration changed during retirement observation"))
	}
	return WorkerMembershipSnapshot{Registration: registration, Sequence: entry.Sequence, Retired: retired, GrantInstanceID: grant.InstanceID,
		GrantRevision: revision, Disabled: grant.Disabled, TerminalOperationID: grant.TerminalOperationID, IdentityResetOperationID: grant.IdentityResetOperationID, Admission: grant.SwarmMembership}, nil
}

func sameMembershipValue(left, right any) bool {
	expected, err := json.Marshal(left, json.Deterministic(true))
	actual, actualErr := json.Marshal(right, json.Deterministic(true))
	return err == nil && actualErr == nil && bytes.Equal(expected, actual)
}

func OpenGrantStore(ctx context.Context, js jetstream.JetStream, replicas int) (*GrantStore, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("host enrollment requires replicated JetStream")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: GrantBucket, History: 2, MaxValueSize: MaxGrantBytes,
		MaxBytes: 64 << 20, Storage: jetstream.FileStorage, Replicas: replicas,
	})
	if err != nil {
		return nil, fmt.Errorf("open host enrollment grants: %w", err)
	}
	status, err := kv.Status(ctx)
	if err != nil || status.Config().Replicas != replicas {
		return nil, errors.New("host enrollment grant replication differs from regional quorum")
	}
	return &GrantStore{kv: kv, js: js}, nil
}

func grantKey(instanceID string) string {
	return entityid.Derive("host-enrollment", instanceID)
}

// Claim creates a grant once, or returns a completed exact replay. A changed
// key, nonce, CSR, or descriptor for the same OCI instance is held.
func (store *GrantStore) Claim(ctx context.Context, candidate Grant) (Grant, uint64, error) {
	if store == nil || store.kv == nil || candidate.SchemaVersion != 1 || candidate.InstanceID == "" ||
		!entityid.Valid(candidate.CreateKey) || len(candidate.DescriptorSHA256) != 64 ||
		len(candidate.Request) == 0 || len(candidate.Request) > 16<<10 || len(candidate.Response) != 0 || candidate.Disabled ||
		candidate.OwnerToken != "" || !candidate.LeaseUntil.IsZero() || candidate.IdentityResetOperationID != "" || candidate.SwarmMembership != nil {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant candidate is invalid"))
	}
	claimToken := make([]byte, 32)
	if _, err := rand.Read(claimToken); err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	candidate.OwnerToken = base64.RawURLEncoding.EncodeToString(claimToken)
	candidate.LeaseUntil = time.Now().UTC().Add(time.Minute)
	wire, err := json.Marshal(candidate)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	key := grantKey(candidate.InstanceID)
	if revision, err := store.kv.Create(ctx, key, wire); err == nil {
		return candidate, revision, nil
	} else if !errors.Is(err, jetstream.ErrKeyExists) {
		return Grant{}, 0, fmt.Errorf("create host enrollment grant: %w", err)
	}
	entry, err := store.kv.Get(ctx, key)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(fmt.Errorf("read host enrollment grant: %w", err))
	}
	var current Grant
	if len(entry.Value()) > MaxGrantBytes || json.Unmarshal(entry.Value(), &current, json.RejectUnknownMembers(true)) != nil ||
		current.SchemaVersion != 1 || current.InstanceID != candidate.InstanceID || current.CreateKey != candidate.CreateKey ||
		current.DescriptorSHA256 != candidate.DescriptorSHA256 || !bytes.Equal(current.Request, candidate.Request) || current.Disabled {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant differs from the immutable first request or is disabled"))
	}
	if len(current.Response) != 0 {
		return current, entry.Revision(), nil
	}
	if time.Now().Before(current.LeaseUntil) {
		return Grant{}, 0, mutationNotApplied(ErrGrantInProgress)
	}
	current.OwnerToken = candidate.OwnerToken
	current.LeaseUntil = candidate.LeaseUntil
	wire, err = json.Marshal(current)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	revision, err := store.kv.Update(ctx, key, wire, entry.Revision())
	if err != nil {
		wrapped := fmt.Errorf("recover host enrollment grant ownership: %w", err)
		if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return Grant{}, 0, mutationNotApplied(wrapped)
		}
		return Grant{}, 0, wrapped
	}
	return current, revision, nil
}

// Forget deletes instanceID's grant, so the instance enrolls afresh: ts-orch
// node rename re-enrolls a renamed static host under its new name (TS-609).
func (store *GrantStore) Forget(ctx context.Context, instanceID string) error {
	if store == nil || store.kv == nil || instanceID == "" {
		return mutationNotApplied(errors.New("host enrollment grant store is unavailable"))
	}
	if err := store.kv.Delete(ctx, grantKey(instanceID)); err != nil && !errors.Is(err, jetstream.ErrKeyNotFound) {
		return fmt.Errorf("forget host enrollment grant: %w", err)
	}
	return nil
}

// Finish persists exact signed bytes before any network response. A lost reply
// returns the identical response on the next exact request.
func (store *GrantStore) Finish(ctx context.Context, expected Grant, revision uint64, response []byte) (Grant, error) {
	if store == nil || store.kv == nil || revision == 0 || expected.Disabled || len(expected.Response) != 0 ||
		expected.OwnerToken == "" || !time.Now().Before(expected.LeaseUntil) ||
		len(response) == 0 || len(response) > 32<<10 {
		return Grant{}, mutationNotApplied(errors.New("host enrollment response cannot be committed"))
	}
	expected.Response = bytes.Clone(response)
	wire, err := json.Marshal(expected)
	if err != nil {
		return Grant{}, mutationNotApplied(err)
	}
	if _, err := store.kv.Update(ctx, grantKey(expected.InstanceID), wire, revision); err != nil {
		wrapped := fmt.Errorf("commit host enrollment response: %w", err)
		if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return Grant{}, mutationNotApplied(wrapped)
		}
		return Grant{}, wrapped
	}
	return expected, nil
}

func (store *GrantStore) Read(ctx context.Context, instanceID string) (Grant, uint64, error) {
	if store == nil || store.kv == nil || instanceID == "" {
		return Grant{}, 0, errors.New("host enrollment grant store is unavailable")
	}
	entry, err := store.kv.Get(ctx, grantKey(instanceID))
	if err != nil {
		return Grant{}, 0, err
	}
	var grant Grant
	if len(entry.Value()) > MaxGrantBytes || json.Unmarshal(entry.Value(), &grant, json.RejectUnknownMembers(true)) != nil || grant.InstanceID != instanceID {
		return Grant{}, 0, errors.New("host enrollment grant is corrupt")
	}
	return grant, entry.Revision(), nil
}

func (store *GrantStore) Disable(ctx context.Context, instanceID string) (uint64, error) {
	for range 4 {
		grant, revision, err := store.Read(ctx, instanceID)
		if err != nil {
			return 0, err
		}
		if grant.Disabled {
			return revision, nil
		}
		grant.Disabled = true
		wire, err := json.Marshal(grant)
		if err != nil {
			return 0, err
		}
		next, err := store.kv.Update(ctx, grantKey(instanceID), wire, revision)
		if err == nil {
			return next, nil
		}
		if !errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return 0, err
		}
	}
	return 0, errors.New("host enrollment grant changed during disable")
}

func (store *GrantStore) ClaimRenew(ctx context.Context, instanceID string, request []byte,
	now time.Time,
) (Grant, uint64, error) {
	if len(request) == 0 || len(request) > 16<<10 {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment renewal request is invalid"))
	}
	grant, revision, err := store.Read(ctx, instanceID)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	// Root reset provenance permits completing a grant without replaying an old response.
	resetPending := len(grant.Response) == 0 && entityid.Valid(grant.IdentityResetOperationID) &&
		grant.SchemaVersion == 1 && entityid.Valid(grant.CreateKey) && len(grant.DescriptorSHA256) == 64 &&
		len(grant.Request) != 0 && len(grant.Request) <= MaxRequestBytes && grant.OwnerToken == "" && grant.LeaseUntil.IsZero() && grant.TerminalOperationID == ""
	if grant.Disabled || len(grant.Response) == 0 && !resetPending {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant is disabled or incomplete"))
	}
	if bytes.Equal(grant.RenewalRequest, request) && len(grant.RenewalResponse) != 0 {
		return grant, revision, nil
	}
	if len(grant.RenewalRequest) != 0 && len(grant.RenewalResponse) == 0 && now.Before(grant.RenewalLeaseUntil) {
		return Grant{}, 0, mutationNotApplied(ErrGrantInProgress)
	}
	var previous Response
	if len(grant.RenewalResponse) != 0 {
		if json.Unmarshal(grant.RenewalResponse, &previous, json.RejectUnknownMembers(true)) != nil ||
			now.Before(previous.ExpiresAt.Add(-24*time.Hour)) {
			return Grant{}, 0, mutationNotApplied(errors.New("host enrollment renewal is not due"))
		}
	} else if len(grant.RenewalRequest) == 0 && !resetPending {
		if json.Unmarshal(grant.Response, &previous, json.RejectUnknownMembers(true)) != nil ||
			now.Before(previous.ExpiresAt.Add(-24*time.Hour)) {
			return Grant{}, 0, mutationNotApplied(errors.New("host enrollment renewal is not due"))
		}
	}
	token := make([]byte, 32)
	if _, err := rand.Read(token); err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	grant.RenewalRequest = bytes.Clone(request)
	grant.RenewalResponse = nil
	grant.RenewalToken = base64.RawURLEncoding.EncodeToString(token)
	grant.RenewalLeaseUntil = now.Add(time.Minute)
	wire, err := json.Marshal(grant)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	next, err := store.kv.Update(ctx, grantKey(instanceID), wire, revision)
	if err != nil {
		wrapped := fmt.Errorf("claim host enrollment renewal: %w", err)
		if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return Grant{}, 0, mutationNotApplied(wrapped)
		}
		return Grant{}, 0, wrapped
	}
	return grant, next, nil
}

func (store *GrantStore) FinishRenew(ctx context.Context, expected Grant, revision uint64,
	response []byte, now time.Time,
) error {
	if store == nil || store.kv == nil || revision == 0 || expected.Disabled ||
		expected.RenewalToken == "" || !now.Before(expected.RenewalLeaseUntil) ||
		len(expected.RenewalRequest) == 0 || len(expected.RenewalResponse) != 0 ||
		len(response) == 0 || len(response) > 32<<10 {
		return mutationNotApplied(errors.New("host enrollment renewal cannot be committed"))
	}
	expected.RenewalResponse = bytes.Clone(response)
	wire, err := json.Marshal(expected)
	if err != nil {
		return mutationNotApplied(err)
	}
	_, err = store.kv.Update(ctx, grantKey(expected.InstanceID), wire, revision)
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
		return mutationNotApplied(err)
	}
	return err
}

func (store *GrantStore) RecordSwarmMembership(ctx context.Context, expected Grant, revision uint64, record SwarmMembership) (Grant, error) {
	if store == nil || store.kv == nil || store.js == nil || revision == 0 || expected.SchemaVersion != 1 || expected.InstanceID == "" ||
		expected.Disabled || expected.TerminalOperationID != "" || expected.IdentityResetOperationID != "" ||
		record.Binding.NodeID == "" || !time.Now().Before(record.Binding.ExpiresAt) ||
		!expected.MatchesCompletedWorkerEnrollment(record.Transport) {
		return Grant{}, mutationNotApplied(errors.New("worker admission differs from current completed instance enrollment"))
	}
	current, currentRevision, err := ReadCurrentGrant(ctx, store.js, expected.InstanceID)
	if err != nil || currentRevision != revision || !sameGrant(current, expected) {
		return Grant{}, mutationNotApplied(errors.New("worker enrollment changed before membership publication"))
	}
	expected.SwarmMembership = &record
	wire, err := json.Marshal(expected)
	if err != nil || len(wire) > MaxGrantBytes {
		return Grant{}, mutationNotApplied(errors.New("worker membership grant is oversized"))
	}
	if _, err := store.kv.Update(ctx, grantKey(expected.InstanceID), wire, revision); err != nil {
		return Grant{}, err
	}
	return expected, nil
}

// MatchesCompletedWorkerEnrollment permits a newly signed worker projection
// while preserving every immutable field of the completed credential response.
// Callers must independently authenticate the request and projected response.
func (grant Grant) MatchesCompletedWorkerEnrollment(transport WorkerTransport) bool {
	return bytes.Equal(transport.Request, grant.Request) && sameWorkerCredentialResponse(transport.Response, grant.Response) ||
		bytes.Equal(transport.Request, grant.RenewalRequest) && sameWorkerCredentialResponse(transport.Response, grant.RenewalResponse)
}

func sameWorkerCredentialResponse(projectedWire, completedWire []byte) bool {
	var projected, completed Response
	if protocol.DecodeStrict(projectedWire, &projected, MaxResponseBytes) != nil || protocol.DecodeStrict(completedWire, &completed, MaxResponseBytes) != nil ||
		projected.Signature == "" || completed.Signature == "" {
		return false
	}
	projected.Swarm, completed.Swarm = nil, nil
	projected.Signature, completed.Signature = "", ""
	left, err := json.Marshal(projected, json.Deterministic(true))
	right, otherErr := json.Marshal(completed, json.Deterministic(true))
	return err == nil && otherErr == nil && bytes.Equal(left, right)
}

func sameSwarmMembership(left, right *SwarmMembership) bool {
	if left == nil || right == nil {
		return left == right
	}
	l, err := json.Marshal(left, json.Deterministic(true))
	r, otherErr := json.Marshal(right, json.Deterministic(true))
	return err == nil && otherErr == nil && bytes.Equal(l, r)
}

