func ReadCurrentGrant(ctx context.Context, js jetstream.JetStream, instanceID string) (Grant, uint64, error) {
	if js == nil || instanceID == "" {
		return Grant{}, 0, errors.New("current enrollment grant reader is unavailable")
	}
	stream, err := grantLeaderReader(js)
	if err != nil {
		return Grant{}, 0, err
	}
	return readCurrentGrant(ctx, stream, instanceID)
}

func grantLeaderReader(js jetstream.JetStream) (nats.JetStreamContext, error) {
	if js == nil || js.Conn() == nil {
		return nil, errors.New("current enrollment grant requires a NATS connection")
	}
	options := js.Options()
	var opts []nats.JSOpt
	if options.Domain != "" {
		opts = append(opts, nats.Domain(options.Domain))
	} else if options.APIPrefix != "" {
		opts = append(opts, nats.APIPrefix(options.APIPrefix))
	}
	// The modern Stream API chooses follower DIRECT.GET for ordinary KV buckets.
	return js.Conn().JetStream(opts...)
}

func readCurrentGrant(ctx context.Context, stream nats.JetStreamContext, instanceID string) (Grant, uint64, error) {
	subject := "$KV." + GrantBucket + "." + grantKey(instanceID)
	entry, err := stream.GetLastMsg("KV_"+GrantBucket, subject, nats.Context(ctx))
	if err != nil {
		return Grant{}, 0, err
	}
	var grant Grant
	if entry == nil || entry.Subject != subject || entry.Sequence == 0 || entry.Header.Get("KV-Operation") != "" || entry.Header.Get(jetstream.MarkerReasonHeader) != "" ||
		protocol.DecodeStrict(entry.Data, &grant, MaxGrantBytes) != nil || grant.SchemaVersion != 1 || grant.InstanceID != instanceID {
		return Grant{}, 0, errors.New("worker enrollment grant is corrupt or deleted")
	}
	return grant, entry.Sequence, nil
}

func OpenGrantStore(ctx context.Context, js jetstream.JetStream, replicas int) (*GrantStore, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("host enrollment requires replicated JetStream")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: GrantBucket, History: 2, MaxValueSize: MaxGrantBytes,
		MaxBytes: 64 << 20, Storage: jetstream.FileStorage, Replicas: replicas,
	})
	if err != nil {
		return nil, fmt.Errorf("open host enrollment grants: %w", err)
	}
	status, err := kv.Status(ctx)
	if err != nil || status.Config().Replicas != replicas {
		return nil, errors.New("host enrollment grant replication differs from regional quorum")
	}
	return &GrantStore{kv: kv, js: js}, nil
}

