func postRuntimeWorkerDocument(ctx context.Context, bundle hostenroll.PublicBundle, path string, wire []byte, status int) ([]byte, error) {
	roots, err := bundle.RootCAs()
	if err != nil {
		return nil, err
	}
	httpTransport := &http.Transport{Proxy: nil, TLSClientConfig: &tls.Config{MinVersion: tls.VersionTLS13, RootCAs: roots}}
	defer httpTransport.CloseIdleConnections()
	client := &http.Client{Transport: httpTransport, Timeout: 20 * time.Second,
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	var last error
	for _, endpoint := range bundle.ControllerEndpoints {
		request, err := http.NewRequestWithContext(ctx, http.MethodPost, "https://"+endpoint+path, bytes.NewReader(wire))
		if err != nil {
			return nil, err
		}
		request.Header.Set("Content-Type", "application/json")
		response, err := client.Do(request)
		if err != nil {
			last = err
			continue
		}
		body, readErr := io.ReadAll(io.LimitReader(response.Body, 2*(hostenroll.MaxRequestBytes+hostenroll.MaxResponseBytes)+1))
		_ = response.Body.Close()
		if response.StatusCode == status && readErr == nil && len(body) <= 2*(hostenroll.MaxRequestBytes+hostenroll.MaxResponseBytes) {
			return body, nil
		}
		last = fmt.Errorf("worker binding admission returned status %d", response.StatusCode)
	}
	return nil, fmt.Errorf("private runtime worker request: %w", last)
}

func (bundle PublicBundle) RootCAs() (*x509.CertPool, error) {
	block, rest := pem.Decode([]byte(bundle.CAPEM))
	if block == nil || block.Type != "CERTIFICATE" || len(strings.TrimSpace(string(rest))) != 0 {
		return nil, errors.New("host enrollment requires one regional CA certificate")
	}
	root, err := x509.ParseCertificate(block.Bytes)
	if err != nil || !root.IsCA || root.KeyUsage&x509.KeyUsageCertSign == 0 || root.CheckSignatureFrom(root) != nil {
		return nil, errors.New("host enrollment regional CA certificate is invalid")
	}
	pool := x509.NewCertPool()
	pool.AddCert(root)
	return pool, nil
}

func selfUpdateRoot(root string) string {
	if root == "" {
		return selfupdate.DefaultRoot
	}
	return root
}

// selfUpdateProofFile returns the configured proof file or, when it is
// unset, the default file the image's watchdog reads, so self-update needs
// no config field.
func selfUpdateProofFile(proofFile, root, unit string) string {
	if proofFile == "" {
		return selfupdate.DefaultProofFile(selfUpdateRoot(root), unit)
	}
	return proofFile
}

func emitSelfUpdateProofWithKey(proofFile, root string, key ed25519.PrivateKey, unit string, output io.Writer) {
	proofFile = selfUpdateProofFile(proofFile, root, unit)
	emitted, err := selfupdate.EmitProof(selfupdate.NewLayout(selfUpdateRoot(root)), unit, proofFile, key, time.Now())
	if err != nil {
		slog.Warn("self-update version proof failed", "error", err)
		return
	}
	if emitted {
		fmt.Fprintf(output, "self-update version proof written to %s\n", proofFile)
	}
}

func DefaultProofFile(root, unit string) string {
	return filepath.Join(filepath.Dir(root), strings.TrimSuffix(unit, ".service"), "selfupdate-proof.json")
}

// EmitProof is called by a healthy process. When an activation for unit is
// pending and this process runs its target, it writes a signed proof to
// proofFile. It returns false when there is nothing to confirm.
func EmitProof(layout Layout, unit, proofFile string, privateKey ed25519.PrivateKey, now time.Time) (bool, error) {
	if !filepath.IsAbs(proofFile) {
		return false, fmt.Errorf("%w: proof file must be absolute", ErrInvalid)
	}
	if err := layout.validate(); err != nil {
		return false, err
	}
	activation, pending, err := layout.Pending()
	if err != nil || !pending || activation.Unit != unit {
		return false, err
	}
	executable, err := os.Readlink("/proc/self/exe")
	if err != nil {
		return false, err
	}
	digest, _, err := hashFile(executable)
	if err != nil {
		return false, err
	}
	if digest != activation.Target {
		return false, nil
	}
	wire, err := SignVersionProof(VersionProof{
		Schema: ProofSchema, ActivationID: activation.ActivationID, Unit: unit,
		BinarySHA256: digest, ProcessID: int64(os.Getpid()), ObservedAt: now.UTC(),
	}, privateKey, now)
	if err != nil {
		return false, err
	}
	return true, writeFileAtomic(proofFile, wire, 0o644)
}

func NewLayout(root string) Layout { return Layout{Root: root, Owner: 0} }

func (layout Layout) validate() error {
	if !filepath.IsAbs(layout.Root) || filepath.Clean(layout.Root) != layout.Root || layout.Owner < 0 {
		return fmt.Errorf("%w: release root must be a clean absolute path", ErrInvalid)
	}
	return nil
}

func (layout Layout) releasesPath() string { return filepath.Join(layout.Root, releasesDir) }
func (layout Layout) currentPath() string  { return filepath.Join(layout.Root, currentLink) }
func (layout Layout) activationPath() string {
	return filepath.Join(layout.Root, activationFile)
}

func (layout Layout) checkOwned(path string, directory bool) error {
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || int(stat.Uid) != layout.Owner || info.Mode().Perm()&0o022 != 0 ||
		directory && !info.IsDir() || !directory && !info.Mode().IsRegular() {
		return fmt.Errorf("%w: %s", ErrUnsafe, path)
	}
	return nil
}

func (layout Layout) Pending() (Activation, bool, error) {
	data, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return Activation{}, false, err
	}
	activation, err := decodeActivation(data)
	if err != nil {
		return Activation{}, false, err
	}
	return activation, true, nil
}

func (layout Layout) pendingRecord() ([]byte, bool, error) {
	if err := layout.checkOwned(layout.activationPath(), false); errors.Is(err, os.ErrNotExist) {
		return nil, false, nil
	} else if err != nil {
		return nil, false, err
	}
	data, err := readBounded(layout.activationPath(), maxStateBytes)
	if err != nil {
		return nil, false, err
	}
	return data, true, nil
}

